  "status": "available",
  "released": "2022",
  "price_usd": 119.0,
  "price_note": "USD 119 direct; battery not included.",
  "price_is_estimate": false,
  "price_checked": "2026-09-06",
  "skill_level": "advanced",
  "skill_note": "Relay work involves two endpoints, Wi-Fi setup and an understanding of EMV flows.",
  "build_effort": "assembled",
