   "radios": [
    {
     "ic": "CC2400",
     "role": "bluetooth",
     "note": "TI 2.4 GHz transceiver. Demodulates 1 Mbps GFSK only - that covers Bluetooth basic rate and BLE 1M PHY, but not EDR's DPSK or BLE 5's 2M and coded PHYs."
    }
   ],
   "display": null,
