  "firmware_repo": "https://github.com/atlas0fd00m/rfcat",
  "firmware_note": "Ships with RfCat pre-installed - it gives you an interactive Python shell that drives the radio directly, which is the whole point of the device.",
  "vendor": "Great Scott Gadgets",
  "vendor_url": "https://greatscottgadgets.com",
  "product_url": "https://greatscottgadgets.com/yardstickone/",
  "category": "subghz",
